cd /app && python3 << 'PYEOF'
import subprocess
import struct

# Read the rodata section to extract float constants
result = subprocess.run(['objdump', '-s', '-j', '.rodata', 'mystery'], capture_output=True, text=True)
lines = result.stdout.split('\n')

floats = []
for line in lines:
    if line.strip() and not 'Contents' in line and not 'section' in line:
        parts = line.split()
        if len(parts) > 1:
            try:
                # Each hex line has address and hex bytes
                hex_bytes = parts[1:]
                for i in range(0, len(hex_bytes), 4):
                    if i+3 < len(hex_bytes):
                        hex_str = hex_bytes[i] + hex_bytes[i+1] + hex_bytes[i+2] + hex_bytes[i+3]
                        if len(hex_str) == 8:
                            try:
                                val = struct.unpack('<f', bytes.fromhex(hex_str))[0]
                                if -1e6 < val < 1e6:
                                    floats.append((hex_str, val))
                            except:
                                pass
            except:
                pass

print("Float constants found:")
for hx, val in sorted(set(floats))[:30]:
    print(f"{hx}: {val}")
PYEOF

